74: func (s *lockoutStore) IncreaseFailedAttempt(userID int32) {
75: 	metricsAccountFailedSignInAttempts.Inc()
76: 
77: 	key := key(userID)
78: 	s.failedAttempts.Increase(key)
79: 
80: 	// Get right after Increase should make the key always exist
